mkdir -p /tmp/work && cat > /tmp/work/run.py <<'E'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"
tok=[None]
def req(path,method="GET"):
    for i in range(200):
        h={}
        if path!="/token" and tok[0]: h["Authorization"]="Bearer "+tok[0]
        r=urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None)
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            body=e.read().decode()[:200]
            if e.code==404: return None
            if e.code==401:
                tok[0]=req("/token","POST")["token"]; continue
            if e.code==429:
                w=e.headers.get("Retry-After")
                try: w=float(w)
                except: 
                    try: w=float(json.loads(body).get("retry_after",1))
                    except: w=1
                print("429 wait",w,body); time.sleep(w); continue
            print("err",e.code,body); time.sleep(1)
        except Exception as e:
            print("exc",e); time.sleep(1)
    raise SystemExit("fail "+path)
tok[0]=req("/token","POST")["token"]
orders={};dups=0;p=1;seen_status=set()
while p:
    d=req(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders: dups+=1
        else: orders[o["id"]]=o
    p=int(d["next"].split("=")[-1]) if d["next"] else None
print(len(orders),dups,d["total_pages"])
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
from collections import Counter
print(Counter(o["status"] for o in orders.values()))
for o in orders.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o); t=t.replace(tzinfo=timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req(f"/customers/{c}")
    if cust[c] is None: print("missing cust",o); continue
    v=o["amount_cents"]*(100-cust[c]["discount_pct"])
    reg[cust[c]["region"]]+=(v*2+100)//200; n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2);print(res)
